-- K4 Fair-Agent: run once in Supabase > SQL Editor.
create table if not exists da_fairs (slug text primary key, data jsonb not null, updated_at timestamptz default now());
create table if not exists da_settings (key text primary key, value jsonb not null);
create table if not exists da_rl (k text primary key, n int not null default 0, ts timestamptz not null default now());

-- Row Level Security ON and NO policies: the public (anon) key can read nothing.
-- Only the Netlify functions, using the service-role key, can read/write.
alter table da_fairs enable row level security;
alter table da_settings enable row level security;
alter table da_rl enable row level security;

create or replace function da_bump(p_k text, p_win int) returns int
language plpgsql security definer set search_path = public as $$
declare r int;
begin
  insert into da_rl(k, n, ts) values (p_k, 1, now())
  on conflict (k) do update set
    n  = case when da_rl.ts < now() - make_interval(secs => p_win) then 1 else da_rl.n + 1 end,
    ts = case when da_rl.ts < now() - make_interval(secs => p_win) then now() else da_rl.ts end
  returning n into r;
  return r;
end $$;
revoke execute on function da_bump(text, int) from public, anon, authenticated;
grant execute on function da_bump(text, int) to service_role;

